function validate([mat, k]) {
  if (!Array.isArray(mat) || mat.length < 2 || mat.length > 100) return 'mat needs 2 to 100 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 2 || n > 100) return 'Each row needs 2 to 100 cells.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    for (let j = 0; j < n; j++) {
      if (row[j] !== 0 && row[j] !== 1) return 'Every cell is 0 or 1.';
      if (j > 0 && row[j] === 1 && row[j - 1] === 0) return 'In each row all 1s must come before the 0s.';
    }
  }
  if (!Number.isInteger(k) || k < 1 || k > mat.length) return 'k is between 1 and the number of rows.';
  return null;
}

