function kWeakestRows(mat, k) {
  const countSoldiers = (row) => {
    let left = 0;
    let right = row.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (row[mid] === 1) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  };

  const rows = mat.map((row, index) => [countSoldiers(row), index]);
  rows.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  return rows.slice(0, k).map(([, index]) => index);
}

