function kWeakestRows(mat, k) {
  const strength = mat.map(row => row.reduce((sum, cell) => sum + cell, 0));
  const taken = new Array(mat.length).fill(false);
  const answer = [];
  for (let step = 0; step < k; step++) {
    let pick = -1;
    for (let i = 0; i < mat.length; i++) {
      if (taken[i]) continue;
      if (pick === -1 || strength[i] < strength[pick]) pick = i;
    }
    taken[pick] = true;
    answer.push(pick);
  }
  return answer;
}

