function generate(rand, size) {
  const m = size === 'large' ? 100 : 2 + Math.floor(rand() * 5);
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 4);
  // Small inputs draw counts from a narrow range so that ties are common.
  const top = size === 'large' ? n : Math.min(n, Math.floor(rand() * (n + 1)));
  const mat = [];
  for (let i = 0; i < m; i++) {
    const soldiers = Math.floor(rand() * (top + 1));
    mat.push(Array.from({ length: n }, (_, j) => (j < soldiers ? 1 : 0)));
  }
  const k = 1 + Math.floor(rand() * m);
  return [mat, k];
}
